import React, { useState, useEffect, useRef } from "react";
import axios from "axios";
import Button from "react-bootstrap/Button";
import Overlay from "react-bootstrap/Overlay";
import Tooltip from "react-bootstrap/Tooltip";
import "../../styles/PositionData.css";
const ip = "192.168.0.45";
const port = 3001;

const PositionData = () => {
  const [positions, setPositions] = useState([]);
  const [queue, setQueue] = useState([]);
  const [missionData, setMissionData] = useState([]);
  const [activeMission, setActiveMission] = useState(null);
  const [tooltipData, setTooltipData] = useState({}); // New state for tooltip data
  const [activeTooltip, setActiveTooltip] = useState(null); // New state for active tooltip
  const [showTooltip, setShowTooltip] = useState(false);
  const [target, setTarget] = useState(null); // State to manage target for Overlay
  const [tooltipContent, setTooltipContent] = useState([]);
  const fetchData = async () => {
    try {
      const response = await axios.get(`http://${ip}:${port}/api/data`);
      setPositions(response.data);
    } catch (error) {
      console.error("Error fetching data:", error);
    }
  };

  const fetchMissionData = async () => {
    try {
      const response = await fetch(`http://${ip}:${port}/api/missionData`);
      const data = await response.json();
      if (data.length > 0) {
        console.log("Received data in the FrontEnd");
        setMissionData(data);
      } else {
        console.log("No new data received");
      }
    } catch (error) {
      console.error("Error fetching mission data:", error);
    }
  };

  const fetchTooltipData = async (queue) => {
    try {
      const response = await fetch(`http://${ip}:${port}/api/missiontoolip`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ tooltipMissionName: queue }),
      });
      if (!response.ok) {
        throw new Error(`HTTP error! Status: ${response.status}`);
      }
      const data = await response.json();
      return data.searchResults;
    } catch (error) {
      console.error("Error fetching tooltip data:", error);
      return [];
    }
  };

  useEffect(() => {
    fetchData();
    fetchMissionData(); // Fetch mission data on component mount
  }, []);

  const handleButtonClick = (position) => {
    setQueue((prevQueue) => {
      const updatedQueue = [...prevQueue, position._id];
      console.log("Item ID", position._id, "added to the queue:", updatedQueue);
      return updatedQueue;
    });
  };

  const handleTrashClick = (position) => {
    const index = queue.indexOf(position._id);
    if (index !== -1) {
      const updatedQueue = [...queue];
      updatedQueue.splice(index, 1);
      setQueue(updatedQueue);
      console.log(
        "Item ID",
        position._id,
        "removed from the queue:",
        updatedQueue
      );
    }
  };

  const sendQueueToServer = () => {
    const missionName = document.getElementById("missionNameInput").value;
    document.getElementById("missionNameInput").value = "";

    if (missionName === "") {
      alert("Mission Name cannot be empty");
      return;
    } else if (queue.length === 0) {
      alert("Choose positions for the task");
      return;
    }

    const mission = { missionName, queue };
    console.log("Sending mission:", mission);

    fetch(`http://${ip}:${port}/api/send`, {
      method: "POST",
      body: JSON.stringify({ mission }),
      headers: {
        "Content-Type": "application/json",
      },
    })
      .then((response) => {
        if (response.ok) {
          console.log("Queue sent successfully.");
          setQueue([]); // Clear queue after sending
          fetchMissionData(); // Refresh data after sending
        } else {
          console.error("Error sending queue:", response.statusText);
        }
      })
      .catch((error) => {
        console.error("Error sending queue:", error);
      });
  };

  const activateMission = () => {
    if (!activeMission || activeMission._id === undefined) {
      alert("Choose a mission");
      return;
    } else {
      const missionName = activeMission.queueData.missionName;
      window.localStorage.setItem(
        "Active Mission is",
        `Active mission is ${missionName}`
      );
      document.getElementById("activemissionname").textContent =
        localStorage.getItem("Active Mission is");

      const missionId = activeMission._id;

      console.log(
        `Active Mission is ${activeMission.queueData.missionName} and id is ${activeMission._id}`
      );
      fetch(`http://${ip}:${port}/api/activeMission`, {
        method: "POST",
        body: JSON.stringify({ missionId }),
        headers: {
          "Content-Type": "application/json",
        },
      })
        .then((response) => {
          if (response.ok) {
            console.log("Mission info sent successfully.");
            setActiveMission(null); // Clear active mission after sending
          } else {
            console.error("Error sending queue:", response.statusText);
          }
        })
        .catch((error) => {
          console.error("Error sending queue:", error);
        });
    }
  };

  const handleClick = async (event, queue) => {
    setTarget(event.target); // Set the target for Overlay

    if (activeTooltip === queue && showTooltip) {
      setShowTooltip(false);
      setActiveTooltip(null);
      return;
    }

    if (!tooltipData[queue]) {
      const data = await fetchTooltipData(queue);
      setTooltipData((prevTooltipData) => ({
        ...prevTooltipData,
        [queue]: data,
      }));
      setTooltipContent(data);
    } else {
      setTooltipContent(tooltipData[queue]);
    }

    setActiveTooltip(queue);
    setShowTooltip(true); // Show tooltip after data is fetched
  };

  return (
    <div>
      <div id="position-container">
        <h1>Position Data</h1>
        <input
          type="text"
          id="missionNameInput"
          placeholder="Enter Task Name"
          style={{
            width: "320px",
            height: "40px",
            marginBottom: "10px",
            borderRadius: "7px",
          }}
        />
        <button
          className="save-task"
          style={{ width: "120px" }}
          onClick={sendQueueToServer}
        >
          Save Task
        </button>
        <div
          id="position-div"
          style={{
            // border: "1px solid black",
            borderRadius: "15px",
            width: "420px",
            maxHeight: "350px",
            overflowY: "auto",
            overflowX: "hidden",
            marginTop: "10px",
          }}
        >
          {positions.map((position, index) => (
            <div
              key={index}
              style={{
                display: "flex",
                alignItems: "center",
                justifyContent: "space-evenly",
                marginBottom: "5px",
                marginTop: "10px",
              }}
            >
              <button
                className="delete"
                style={{
                  width: "150px",
                  border: "none",
                  backgroundColor: "#00acc1",
                  color: "white",
                  borderRadius: "5px",
                  height: "40px",
                }}
                onClick={() => handleButtonClick(position)}
              >
                {position.name}
              </button>
              <i
                className="fa-solid fa-trash-can"
                style={{
                  cursor: "pointer",
                  color: "#E40078",
                  fontSize: "30px",
                }}
                onClick={() => handleTrashClick(position)}
              ></i>
            </div>
          ))}
        </div>
      </div>
      <div className="container">
        <h1 className="title">Task Data</h1>
        <button
          id="activatemission"
          className="activate-button"
          onClick={activateMission}
        >
          Activate Task
        </button>

        <div id="activemissionname" style={{ margin: "10px 0" }}></div>
        <div className="div-button">
          {missionData.map((item) => (
            <div key={item.queueData.missionName}>
              <button
                className="task-button"
                onClick={() => setActiveMission(item)}
              >
                {item.queueData.missionName}
              </button>
              <Button
                className="info-button"
                onClick={(e) => handleClick(e, item.queueData.queue)}
              >
                &#9432;
              </Button>

              <Overlay target={target} show={showTooltip} placement="right">
                {(props) => (
                  <Tooltip id="overlay-example" {...props}>
                    <div
                      style={
                        {
                          // backgroundColor: "white",
                          // border: "1px solid black",
                          // padding: "10px",
                          // borderRadius: "5px",
                        }
                      }
                    >
                      <ul>
                        {tooltipContent.map((data, idx) => (
                          <li key={idx}>{data}</li>
                        ))}
                      </ul>
                    </div>
                  </Tooltip>
                )}
              </Overlay>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default PositionData;
