import React, { useState, useEffect } from "react";
import "../styles/Header.css";
import "../styles/mainstyle.css";
import ham from "../images/ham.png";
import logo from "../images/logo.png";
import play from "../images/play.png";
import pause from "../images/pause.png";
import emergency from "../images/emergency.png";
import ROSLIB from "roslib";
import MenuTree from "./MenuTree";

const Header = ({ toggleMenu }) => {
  const [isPlaying, setIsPlaying] = useState(false);
  const [ros, setRos] = useState(null);
  const [twist, setTwist] = useState(null);

  useEffect(() => {
    const newRos = new ROSLIB.Ros({
      url: "ws://192.168.0.45:9092",
    });
    setRos(newRos);

    return () => {
      newRos.close();
    };
  }, []);

  useEffect(() => {
    if (!ros) return;
    const newTwist = new ROSLIB.Message({
      linear: { x: 0.0, y: 0.0, z: 0.0 },
      angular: { x: 0.0, y: 0.0, z: 0.0 },
    });
    setTwist(newTwist);
  }, [ros]);

  const pauseRobot = () => {
    console.log("Pausing robot...");
    if (!ros || !twist) {
      console.error("ROS or Twist message is not initialized.");
      return;
    }
    twist.linear.x = 0.0;
    twist.angular.z = 0.0;

    const cmdVelTopic = new ROSLIB.Topic({
      ros: ros,
      name: "/cmd_vel",
      messageType: "geometry_msgs/Twist",
    });
    cmdVelTopic.publish(twist);
    console.log("Robot paused successfully.");
  };

  const handlePlayPause = () => {
    setIsPlaying(!isPlaying);
  };

  return (
    <div id="navbar" className="header-container">
      <div id="left">
        <img
          src={ham}
          className="icn menuicn"
          id="menuicn"
          alt="menu-icon"
          onClick={toggleMenu}
        />
        <div id="logo">
          <img
            src={logo}
            className="icn1 menuicn"
            id="menuicn"
            alt="menu-icon"
          />
        </div>
        <div id="name">Name Of Current User</div>
      </div>
      <div id="right">
        <div id="playbutton" onClick={handlePlayPause}>
          <img
            src={isPlaying ? pause : play}
            className="icn2 menuicn"
            id="menuicn"
            alt="menu-icon"
          />
        </div>
        <div id="emgncybutton">
          <img
            src={emergency}
            className="icn3 menuicn"
            id="menuicn"
            alt="menu-icon"
          />
        </div>
        <div id="mission">
          <p>Mission in queue</p>
          <button id="pausedbtn">Paused</button>
        </div>
        <div id="battery">80|||</div>
      </div>
    </div>
  );
};

export default Header;
