import React, { useState } from "react";
import Header from "../src/components/Header";
import Body from "../src/components/Body";
import MenuTree from "../src/components/MenuTree";
import "../src/styles/App.css"; // Make sure to create this file if it doesn't exist

function App() {
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  const toggleMenu = () => {
    console.log("Toggle menu called");

    setIsMenuOpen(!isMenuOpen);
    const bodyElement = document.querySelector(".body-container");
    if (bodyElement) {
      bodyElement.style.marginLeft = isMenuOpen ? "0" : "250px";
    }
  };

  return (
    <div className="App">
      <Header toggleMenu={toggleMenu} />
      <MenuTree isOpen={isMenuOpen} />
      <div className="body-container">
        <Body />
      </div>
    </div>
  );
}

export default App;
